const ponto = flow.get("ponto") || {};
const operadoresDisponiveis = (msg.payload || []).filter(o => ponto[o.codigo_operador] === "dentro");
if (!Array.isArray(operadoresDisponiveis) ||
    operadoresDisponiveis.length === 0) {
    node.warn("Sem operadores dentro do horário. Evento não criado.");
    return null;
}

const maquinas = [
    { maquina: "M001", op: "2609394", ciclo: 12 },
    { maquina: "M002", op: "2609395", ciclo: 15 },
    { maquina: "M003", op: "2609396", ciclo: 20 }
];

const DURACAO_EVENTO = 60;

const selecionada =
    maquinas[Math.floor(Math.random() * maquinas.length)];

const operador =
    operadoresDisponiveis[
    Math.floor(Math.random() * operadoresDisponiveis.length)
    ];

const tipos = ["PRODUCAO", "PARAGEM", "MANUTENCAO"];
const tipo = tipos[Math.floor(Math.random() * tipos.length)];

const fim = new Date();
const inicio = new Date(fim.getTime() - DURACAO_EVENTO * 1000);

let estado;
let motivo = null;
let produzidas = 0;
let rejeitadas = 0;
let espera = 0;
let intervencao = 0;

if (tipo === "PRODUCAO") {
    estado = "PRODUCAO";
    const maximo = Math.floor(DURACAO_EVENTO / selecionada.ciclo);
    produzidas = Math.max(1, Math.round(maximo * (0.6 + Math.random() * 0.4)));
    for (let i = 0; i < produzidas; i++) {
        if (Math.random() < 0.10) rejeitadas++;
    }
} else if (tipo === "PARAGEM") {
    estado = "PARADA";
    motivo = "Avaria simulada";
    espera = 60;
} else {
    estado = "MANUTENCAO";
    motivo = "Manutencao preventiva simulada";
    intervencao = 60;
}

msg.params = [
    selecionada.maquina,
    inicio,
    fim,
    estado,
    tipo,
    produzidas,
    rejeitadas,
    selecionada.op,
    motivo,
    espera,
    intervencao,
    operador.id
];

return msg;

