// pasta do projeto: variável de ambiente PROJETO_DIR do separador (Flow 1 > Properties > Environment)
const CSV = env.get("PROJETO_DIR") + "/data/input/picagens.csv";
const PAUSAS = {                 // pela hora de início do horário
    "06:30": ["11:00", "11:30"], // Turno 1
    "14:30": ["19:00", "19:30"], // Turno 2
    "22:30": ["02:00", "02:30"], // Turno 3
    "08:00": ["12:30", "13:20"]  // Horario8H
};

const DIA = 24 * 60;
const minutos = hhmm => { const [h, m] = hhmm.split(":").map(Number); return h * 60 + m; };
const norm = m => ((m % DIA) + DIA) % DIA;
const dentro = (agora, i, f) => (i <= f ? agora >= i && agora < f : agora >= i || agora < f);
const p2 = n => String(n).padStart(2, "0");
const formatar = d => `${p2(d.getDate())}/${p2(d.getMonth() + 1)}/${d.getFullYear()} ${p2(d.getHours())}:${p2(d.getMinutes())}`;
// primeira vez, depois de 'depois', em que o relógio marca 'minuto'
function proxima(depois, minuto) {
    const d = new Date(depois.getTime());
    d.setHours(Math.floor(minuto / 60), minuto % 60, 0, 0);
    if (d <= depois) d.setDate(d.getDate() + 1);
    return d;
}

// 1. última picagem de cada operador, lida do CSV
const ultima = {};
let texto = "";
try { texto = fs.readFileSync(CSV, "utf8"); } catch (e) { node.warn("Não consegui ler " + CSV); }
for (const linha of texto.split(/\r?\n/)) {
    const m = linha.match(/^(\d+);(\d{2})\/(\d{2})\/(\d{4}) (\d{2}):(\d{2});(ENTRADA|SAIDA)$/);
    if (!m) continue;
    const quando = new Date(+m[4], +m[3] - 1, +m[2], +m[5], +m[6]);
    if (!ultima[m[1]] || quando >= ultima[m[1]].quando) ultima[m[1]] = { tipo: m[7], quando };
}

// 2. decidir as picagens deste minuto
const operadores = Array.isArray(msg.payload) ? msg.payload : [];
const agoraData = new Date();
agoraData.setSeconds(0, 0);
const agora = agoraData.getHours() * 60 + agoraData.getMinutes();
const linhas = [];
const ponto = {};

for (const op of operadores) {
    const c = op.codigo_operador;
    const inicio = minutos(op.inicio), fim = minutos(op.fim);
    const entrada = norm(inicio - 2), saida = norm(fim + 2);
    let pIni = null, pFim = null;
    if (op.pausa_minutos > 0) {
        if (PAUSAS[op.inicio]) [pIni, pFim] = PAUSAS[op.inicio].map(minutos);
        else { pIni = norm(inicio + Math.round((norm(fim - inicio) - op.pausa_minutos) / 2)); pFim = norm(pIni + op.pausa_minutos); }
    }
    const deveTrabalhar = dentro(agora, entrada, saida) && !(pIni !== null && dentro(agora, pIni, pFim));
    let estaDentro = ultima[c] && ultima[c].tipo === "ENTRADA";

    // estava dentro: já passou a fronteira de saída (pausa ou fim do turno)?
    if (estaDentro) {
        const desde = ultima[c].quando;
        let fronteira = proxima(desde, saida);
        if (pIni !== null) { const p = proxima(desde, pIni); if (p < fronteira) fronteira = p; }
        if (agoraData >= fronteira) {
            linhas.push(`${c};${formatar(fronteira)};SAIDA`);
            estaDentro = false;
        }
    }
    // está fora e devia estar a trabalhar: pica a entrada agora (atrasada, se for o caso)
    if (!estaDentro && deveTrabalhar) {
        linhas.push(`${c};${formatar(agoraData)};ENTRADA`);
        estaDentro = true;
    }
    if (estaDentro) ponto[c] = "dentro";
}
// operadores desativados que ficaram dentro: picam a saída agora
for (const c of Object.keys(ultima)) {
    if (ultima[c].tipo === "ENTRADA" && !operadores.some(o => o.codigo_operador === c)) {
        linhas.push(`${c};${formatar(agoraData)};SAIDA`);
    }
}

flow.set("ponto", ponto);   // o simulador (function 1) só gera eventos para quem está dentro
node.status({ text: "dentro: " + (Object.keys(ponto).join(", ") || "ninguém") });
if (linhas.length === 0) return null;
return [linhas.map(l => ({ payload: l, filename: CSV }))];   // o nó seguinte escreve no mesmo ficheiro
